def knapsack(items, capacity):
    dp = [0] * (capacity + 1)

    for weight, value in items:
        if weight <= capacity:
            for remaining in range(capacity, weight - 1, -1):
                dp[remaining] = max(
                    dp[remaining],
                    dp[remaining - weight] + value
                )

    return dp[capacity]
